#ifndef MY_NODE
#define MY_NODE 0x05
#endif

/* This hub's 1 LOCAL link(s) (ADR-0006):
      link 0 (up): the parent backplane
   */
#define ACT_HUB_N_LINKS 1

/* Optional per-loop telemetry hook (§08). The glue calls act_hub_post_control() at
   the end of every control_tick. The device file can provide its own by doing
   `#define ACT_HUB_POST_CONTROL_OVERRIDE` BEFORE including this header (then
   implementing act_hub_post_control() itself); otherwise this no-op default is used. */
#ifndef ACT_HUB_POST_CONTROL_OVERRIDE
extern "C" void act_hub_post_control(void) {}
#endif

/* One floor per floored command port (§05) — born-disarmed, safe at boot. */
static Floor g_floor_effort_cmd;
static uint16_t g_applied_seq_effort_cmd = 0;  /* last command seq we handed the floor */
#define FLOOR_WINDOW_MS_EFFORT_CMD (FLOOR_MISSES_ACT_HUB_EFFORT_CMD * CMD_PERIOD_MS_ACT_HUB_EFFORT_CMD)

/* Per-status-port seq. */
static uint16_t g_status_seq_act_status = 0;
/* A command for effort_cmd: hand the floor the RAW PACKED VALUE BYTES +
   its seq — the floor watches the seq, not the value, and stores the bytes
   opaquely (ADR-0005). Record applied_seq for the status report (§05). */
static void on_command_effort_cmd(const Frame *f) {
  if (f->port != PORT_ACT_HUB_EFFORT_CMD) return;
  if (f->payload_len < 4) return;
  floor_on_command(&g_floor_effort_cmd, f->seq, f->payload, f->payload_len);
  g_applied_seq_effort_cmd = f->seq;
}
/* The drive loop — period 0 so it runs every loop pass, never starved (§08).
   Each floor gates its own port: target while armed, safe action otherwise
   (default safe). The floor hands back the PACKED VALUE BYTES (ADR-0005); the
   glue decodes them to the hook's typed param. Then the optional per-loop
   device hook (telemetry). */
static void control_tick(uint32_t now_us) {
  uint32_t now_ms = now_us / 1000u;
  uint8_t drive_effort_cmd[FLOOR_MAX_VALUE];
  floor_tick(&g_floor_effort_cmd, now_ms, drive_effort_cmd);
  act_hub_effort_cmd_drive(be_get_f32(&drive_effort_cmd[0]));
  act_hub_post_control();
}
/* IN ports are event-driven via on_command; the scheduled cmd tick is a no-op. */
static void effort_cmd_cmd_tick(uint32_t now_us) { (void)now_us; }
/* Report act_status's reported truth (§05): the paired floor's applied_seq +
   floored? flag, so the host reads truth instead of inferring it. */
static void act_status_sample_tick(uint32_t now_us) {
  (void)now_us; /* status omits t_dev, so the tick needs no clock */
  Frame f;
  f.node = MY_NODE;
  f.port = PORT_ACT_HUB_ACT_STATUS;
  f.seq = ++g_status_seq_act_status;
  f.stamped = PORT_ACT_HUB_ACT_STATUS_STAMPED;
  f.t_dev = 0;

  be_put_u16(&f.payload[0], g_applied_seq_effort_cmd);
  f.payload[2] = g_floor_effort_cmd.armed ? 0 : 1; /* floored? = not armed */
  f.payload_len = 3;

  link_send_up(&f);
}

static Router g_router;

static void deliver_local(const Frame *f, void *) {
  if (f->port == PORT_ACT_HUB_EFFORT_CMD) on_command_effort_cmd(f);
}
static void send_on_link(uint8_t link, const Frame *f, void *) {
  link_send_on_link(link, f); /* leaf: only link 0 (up toward the parent) is ever requested */
}


/* Meaning-blind inbound (§04): decode the body (CRC-clean at the seam), learn
   t_dev-ness per port just-in-time, route by DIRECTION + NODE (ADR-0006,
   ADR-0011): a downlink arrival ascends to link 0; a parent arrival is
   dispatched by NODE → a LOCAL LINK INDEX. seq/t_dev never touched. */
extern "C" void hub_on_body(uint8_t arrival_link, const uint8_t *body, size_t len) {
  if (len < FRAME_HEADER_BASE_SIZE) return;
  Frame f;
  bool stamped = wire_port_stamped(body[0], body[1]); /* per-port t_dev (§04) */
  if (!frame_decode_body(body, len, stamped, &f)) return;
  RouterSinks sinks = {deliver_local, send_on_link, nullptr};
  router_route(&g_router, &f, arrival_link, &sinks);
}
extern "C" void hub_setup(void) {
  /* born-disarmed floors first (§05), so the safe output is selected before any drive */
  floor_init(&g_floor_effort_cmd, FLOOR_WINDOW_MS_EFFORT_CMD, SAFE_ACT_HUB_EFFORT_CMD, SAFE_N_ACT_HUB_EFFORT_CMD); /* %{nm: 0.0} */

  g_router.my_node = MY_NODE;
  for (int i = 0; i < 256; i++) g_router.route_table[i] = 0; /* default: link 0, the up-link toward the parent/host */
  g_router.route_table[0x05] = LINK_LOCAL_IDX; /* MY_NODE — delivered to a local port */

  act_hub_device_setup(); /* the hand-written hardware bring-up */
}
/* The schedule (§08): one {period_us, tick} row per port from its rate. The
   drive loop runs EVERY loop (period 0) and is prepended here, never starved. */
static Task act_hub_tasks[] = {
  { 0, 0, control_tick },  /* period 0 → every loop pass */
  { 20000, 0, act_status_sample_tick }  /* act_status @ 50 Hz */,
  { 20000, 0, effort_cmd_cmd_tick }  /* effort_cmd @ 50 Hz */
};
#define ACT_HUB_N_TASKS (sizeof(act_hub_tasks) / sizeof(act_hub_tasks[0]))

extern "C" Task *hub_tasks(size_t *n_tasks) {
  *n_tasks = ACT_HUB_N_TASKS;
  return act_hub_tasks;
}
